/**  Install progress, streamed to the webview. */
export type InstallProgress = 
/**  Downloading: bytes received of total. */
{ step: "downloading"; 
/**  Bytes received. */
received: number; 
/**  Total bytes. */
total: number } | 
/**  Checking checksums and the code signature. */
{ step: "verifying" } | 
/**  Moving the binary into place. */
{ step: "installing" };

/**  A detected problem. */
