/**  How bad an issue is. */
export type Severity = 
/**  Something doesn't work. */
"error" | 
/**  Something may stop working, or needs attention. */
"warning" | 
/**  Worth knowing; nothing is broken. */
"info";

/**  Live traffic numbers for a share. */
